/* HEXA BATTLEGROUNDS setup — PART 84 OF 84. Run parts in order. Safe to re-run. */ create or replace function _online_launch(p_arena uuid, p_why text) returns jsonb language plpgsql as $$ declare a arenas; v_ev uuid; v_size int; v_seal jsonb; v_next uuid; t record; k int := 0; v_bus int := 0; v_squads int; v_len text; begin select * into a from arenas where id = p_arena for update; if a.id is null or a.autopilot or a.phase <> 'lobby' then return null; end if; v_ev := a.event_id; v_size := _online_map_size(v_ev); v_seal := _online_seal_map(p_arena); for t in select tm.id, tm.ready from teams tm where tm.arena_id = p_arena order by tm.ready desc, _online_size(tm.id) desc, tm.created_at loop k := k + 1; if not t.ready or k > v_size then if v_next is null then select id into v_next from arenas where event_id = v_ev and phase = 'lobby' and not autopilot and id <> p_arena order by number limit 1; if v_next is null then begin v_next := _online_new_lobby(v_ev); exception when others then v_next := null; end; end if; end if; if v_next is not null then update teams set arena_id = v_next, bus = null where id = t.id; end if; end if; end loop; select count(*) into v_squads from teams where arena_id = p_arena and ready; if v_squads = 0 then return null; end if; for t in select id from teams where arena_id = p_arena order by number loop update teams set bus = 1 + v_bus / greatest(1, _cfg(v_ev, 'bus_size')) where id = t.id; v_bus := v_bus + 1; end loop; v_len := coalesce(_cfg_text(v_ev, 'online_auto_length'), 'standard'); update arenas set autopilot = true, auto_length = v_len, auto_story = -1, fill_deadline = null where id = p_arena; perform _auto_resync(p_arena); perform _tick(p_arena, true); insert into audit_log(event_id, arena_id, actor, action, args) values (v_ev, p_arena, 'online', 'map_launched', jsonb_build_object('squads', v_squads, 'why', p_why) || v_seal); perform _feed(p_arena, 'map.launched', jsonb_build_object('squads', v_squads)); perform _ping_arena(p_arena, 'phase'); if v_next is not null then perform _ping_arena(v_next, 'roster'); end if; return jsonb_build_object('map', a.number, 'squads', v_squads, 'why', p_why); end $$; create or replace function _online_auto_check(p_ev uuid, p_force boolean default false) returns jsonb language plpgsql as $$ declare a record; v_size int; v_teams int; v_ready int; v_players int; v_out jsonb := '[]'::jsonb; r jsonb; v_fill int; v_full int; v_min int; begin if _cfg(p_ev, 'online_auto') <> 1 or _cfg(p_ev, 'online_started') = 1 then return v_out; end if; if p_force then perform pg_advisory_xact_lock(hashtext('online:' || p_ev::text)); elsif not pg_try_advisory_xact_lock(hashtext('online:' || p_ev::text)) then return v_out; end if; v_size := _online_map_size(p_ev); v_fill := _cfg(p_ev, 'online_fill_seconds'); v_full := _cfg(p_ev, 'online_full_wait'); v_min := _cfg(p_ev, 'online_min_players'); for a in select id, number, fill_deadline from arenas where event_id = p_ev and phase = 'lobby' and not autopilot order by number loop select count(*), count(*) filter (where n >= 3), coalesce(sum(n), 0) into v_teams, v_ready, v_players from (select (select count(*) from players q where q.team_id = t.id and q.active) n from teams t where t.arena_id = a.id) s where n > 0; continue when v_teams = 0; r := null; if p_force and v_players >= 2 then r := _online_launch(a.id, 'host'); elsif v_teams >= v_size and v_ready = v_teams then r := _online_launch(a.id, 'full'); elsif a.fill_deadline is not null and now() >= a.fill_deadline then if v_players >= v_min then r := _online_launch(a.id, 'countdown'); else update arenas set fill_deadline = now() + interval '60 seconds' where id = a.id; end if; elsif a.fill_deadline is null and (v_players >= v_min or v_teams >= v_size) then update arenas set fill_deadline = now() + make_interval(secs => case when v_teams >= v_size then v_full else v_fill end) where id = a.id; perform _ping_arena(a.id, 'phase'); elsif v_teams >= v_size and a.fill_deadline > now() + make_interval(secs => v_full) then update arenas set fill_deadline = now() + make_interval(secs => v_full) where id = a.id; perform _ping_arena(a.id, 'phase'); end if; if r is not null then v_out := v_out || r; end if; exit when p_force and r is not null; end loop; return v_out; end $$; create or replace function host_online_auto(p_token text, p_length text default 'standard', p_on boolean default true) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); if _cfg(v_ev, 'online') <> 1 then raise exception 'NOT_ONLINE_EVENT'; end if; if _cfg(v_ev, 'online_started') = 1 then raise exception 'ALREADY_STARTED'; end if; if coalesce(p_length, 'standard') not in ('quick', 'standard', 'full') then raise exception 'BAD_LENGTH'; end if; if coalesce(p_on, true) then update events set settings = settings || _auto_preset(coalesce(p_length, 'standard')) || jsonb_build_object('online_auto', 1, 'online_auto_length', coalesce(p_length, 'standard')) where id = v_ev; else update events set settings = settings || jsonb_build_object('online_auto', 0) where id = v_ev; update arenas set fill_deadline = null where event_id = v_ev and phase = 'lobby' and not autopilot; end if; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', case when coalesce(p_on, true) then 'online_auto_on' else 'online_auto_off' end, jsonb_build_object('length', p_length)); perform _online_auto_check(v_ev, false); return host_online_summary(p_token); end $$; create or replace function host_online_launch(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; r jsonb; begin v_ev := _auth_host(p_token); if _cfg(v_ev, 'online_auto') <> 1 then raise exception 'AUTO_OFF'; end if; r := _online_auto_check(v_ev, true); if jsonb_array_length(r) = 0 then raise exception 'NO_READY_SQUADS'; end if; return r -> 0; end $$; drop function if exists _host_online_start_v12(text, text); alter function host_online_start(text, text) rename to _host_online_start_v12; create function host_online_start(p_token text, p_length text default 'standard') returns jsonb language plpgsql security definer set search_path = public as $$ begin if _cfg(_auth_host(p_token), 'online_auto') = 1 then raise exception 'AUTO_ON'; end if; return _host_online_start_v12(p_token, p_length); end $$; drop function if exists _host_online_summary_v12(text); alter function host_online_summary(text) rename to _host_online_summary_v12; create function host_online_summary(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v jsonb; begin v_ev := _auth_host(p_token); perform _online_auto_check(v_ev, false); v := _host_online_summary_v12(p_token); v := v || jsonb_build_object('auto', _cfg(v_ev, 'online_auto') = 1, 'auto_length', _cfg_text(v_ev, 'online_auto_length'), 'map_size', _online_map_size(v_ev), 'fill_seconds', _cfg(v_ev, 'online_fill_seconds')); v := jsonb_set(v, '{maps}', (select coalesce(jsonb_agg(m || jsonb_build_object( 'launched', a.autopilot or a.phase <> 'lobby', 'fill_deadline', a.fill_deadline) order by a.number), '[]'::jsonb) from jsonb_array_elements(v -> 'maps') m join arenas a on a.id = (m ->> 'id')::uuid)); return v; end $$; drop function if exists _player_state_v12(text); alter function player_state(text) rename to _player_state_v12; create function player_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; a arenas; v_ev uuid; v_size int; v_teams int; v_ready int; v_players int; begin v := _player_state_v12(p_token); if jsonb_typeof(v -> 'online') <> 'object' then return v; end if; select * into a from arenas where id = (v -> 'arena' ->> 'id')::uuid; v_ev := a.event_id; if _cfg(v_ev, 'online_auto') <> 1 or _cfg(v_ev, 'online_started') = 1 then return v; end if; if a.phase = 'lobby' and not a.autopilot then v_size := _online_map_size(v_ev); select count(*), count(*) filter (where n >= 3), coalesce(sum(n), 0) into v_teams, v_ready, v_players from (select (select count(*) from players q where q.team_id = t.id and q.active) n from teams t where t.arena_id = a.id) s where n > 0; if (a.fill_deadline is not null and now() >= a.fill_deadline) or (a.fill_deadline is null and v_players >= _cfg(v_ev, 'online_min_players')) or v_teams >= v_size then if jsonb_array_length(_online_auto_check(v_ev, false)) > 0 then v := _player_state_v12(p_token); end if; select * into a from arenas where id = (v -> 'arena' ->> 'id')::uuid; end if; end if; v := jsonb_set(v, '{online,auto}', 'true'::jsonb); v := jsonb_set(v, '{online,started}', to_jsonb(a.autopilot or a.phase <> 'lobby')); if a.phase = 'lobby' and not a.autopilot then select count(*), count(*) filter (where n >= 3) into v_teams, v_ready from (select (select count(*) from players q where q.team_id = t.id and q.active) n from teams t where t.arena_id = a.id) s where n > 0; v := jsonb_set(v, '{online,fill}', jsonb_build_object('map', a.number, 'squads', v_teams, 'ready', v_ready, 'size', _online_map_size(v_ev), 'deadline', a.fill_deadline)); end if; return v; end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift', 'online_join', 'squad_chat_send', 'squad_chat', 'host_attendance', 'host_online_summary', 'host_online_start', 'host_online_auto', 'host_online_launch']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;
